  // Validate required fields
  if (!newProduct.name || newProduct.name.trim() === '') {
    throw new Error('Product name is required');
  }

  if (!newProduct.price || newProduct.price <= 0) {
    throw new Error('Price must be greater than 0');
  }

  if (!newProduct.quantity || newProduct.quantity <= 0) {
    throw new Error('Quantity must be greater than 0');
  }

  if (!newProduct.category) {
    throw new Error('Category is required');
  }

  if (!newProduct.location || newProduct.location.trim() === '') {
    throw new Error('Growing location is required');
  }

  if (!newProduct.images || newProduct.images.length === 0) {
    throw new Error('At least one product image is required');
  }

  // Generate unique ID and prepare product data
  const productToSave = {
    ...newProduct,
    id: 'prod_' + Date.now(),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  // Add to userProducts array
  const currentProducts = variables['b6eb0901-f9a1-42eb-80fe-480dae731f61'] || [];
  variables['b6eb0901-f9a1-42eb-80fe-480dae731f61'] = [...currentProducts, productToSave];

  // Reset form
  variables['c34970b4-4f64-4368-8fee-2c2a5a2dd9a9'] = {
    name: '',
    description: '',
    price: 0,
    unit: 'lb',
